begin;
create table public.avisos_automaticos(id uuid primary key default gen_random_uuid(),oficina_id uuid not null references public.oficinas(id),cliente_id uuid not null,ordem_servico_id uuid,versao_orcamento_id uuid,chave text not null,mensagem text not null,situacao text not null default 'revisao' check(situacao in('revisao','aprovado','enviando','enviado','incerto','cancelado')),aprovado_por uuid references auth.users(id),aprovado_em timestamptz,telefone_aprovado text,tentativa uuid,iniciado_em timestamptz,enviado_em timestamptz,criado_em timestamptz not null default now(),unique(oficina_id,chave),foreign key(oficina_id,cliente_id) references public.clientes(oficina_id,id),foreign key(oficina_id,ordem_servico_id) references public.ordens_servico(oficina_id,id),foreign key(oficina_id,versao_orcamento_id) references public.versoes_orcamento(oficina_id,id));
alter table public.avisos_automaticos enable row level security;
revoke all on public.avisos_automaticos from public,anon,authenticated;
create function private.aviso_andamento() returns trigger language plpgsql security definer set search_path='' as $$
declare msg text;begin if new.situacao=old.situacao then return new;end if;
 if private.has_feature(new.oficina_id,'automations') then
 msg:=case new.situacao when 'in_progress' then 'Seu veículo está em serviço.' when 'ready' then 'Seu veículo está pronto. Entre em contato para combinar a retirada.' when 'delivered' then 'Seu veículo foi entregue. Obrigado pela confiança!' else null end;
 if msg is not null then insert into public.avisos_automaticos(oficina_id,cliente_id,ordem_servico_id,chave,mensagem) values(new.oficina_id,new.cliente_id,new.id,'os:'||new.id||':'||new.situacao||':'||gen_random_uuid(),msg||' OS #'||new.numero) on conflict do nothing;end if;end if;
 insert into public.historico_ordem_servico(oficina_id,ordem_servico_id,tipo_evento,descricao,visivel_ao_cliente,usuario_autor_id) values(new.oficina_id,new.id,'status_changed',case new.situacao when 'received' then 'Veículo recebido' when 'in_progress' then 'Serviço em andamento' when 'waiting' then 'Aguardando continuidade' when 'ready' then 'Pronto para entrega' when 'delivered' then 'Veículo entregue' when 'cancelled' then 'Atendimento cancelado' else 'Situação do atendimento atualizada' end,true,auth.uid());return new;end $$;
create trigger aviso_andamento after update of situacao on public.ordens_servico for each row execute function private.aviso_andamento();
create function public.consultar_automacoes(p_oficina uuid) returns jsonb language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'automations');return (select coalesce(jsonb_agg(jsonb_build_object('id',a.id,'mensagem',a.mensagem,'situacao',a.situacao,'criado_em',a.criado_em,'cliente',c.nome,'telefone',c.telefone_e164) order by a.criado_em desc),'[]') from (select * from public.avisos_automaticos where oficina_id=p_oficina order by criado_em desc limit 100) a join public.clientes c on c.id=a.cliente_id and c.oficina_id=a.oficina_id);end $$;
create function public.revisar_aviso(p_oficina uuid,p_id uuid,p_aprovar boolean) returns void language plpgsql security definer set search_path='' as $$
begin perform private.exigir_gestao(p_oficina,'automations');update public.avisos_automaticos a set situacao=case when p_aprovar then 'aprovado' else 'cancelado' end,aprovado_por=auth.uid(),aprovado_em=now(),telefone_aprovado=c.telefone_e164 from public.clientes c where a.id=p_id and a.oficina_id=p_oficina and c.oficina_id=a.oficina_id and c.id=a.cliente_id and a.situacao='revisao' and (not p_aprovar or (c.arquivado_em is null and c.telefone_e164~'^\+[1-9][0-9]{7,14}$'));if not found then raise exception 'Aviso indisponível ou cliente sem telefone válido.' using errcode='22023';end if;end $$;
-- Somente o backend confiável pode consumir a fila. O n8n recebe apenas um segredo de agendamento.
create function public.processar_lembretes_automaticos() returns integer language plpgsql security definer set search_path='' as $$
declare n integer;begin
 insert into public.avisos_automaticos(oficina_id,cliente_id,versao_orcamento_id,chave,mensagem) select q.oficina_id,q.cliente_id,v.id,'lembrete:'||v.id,'Seu orçamento #'||q.numero||' aguarda uma resposta. Fale com a oficina se precisar de ajuda.' from public.orcamentos q join public.versoes_orcamento v on v.oficina_id=q.oficina_id and v.id=q.versao_atual_id join public.clientes c on c.oficina_id=q.oficina_id and c.id=q.cliente_id where q.situacao='awaiting_approval' and v.publicado_em<now()-interval '1 day' and v.expira_em>now() and c.arquivado_em is null and private.has_feature(q.oficina_id,'automations') on conflict(oficina_id,chave) do nothing;get diagnostics n=row_count;
 update public.avisos_automaticos set situacao='incerto' where situacao='enviando' and iniciado_em<now()-interval '10 minutes';return n;end $$;
create function public.reservar_aviso_automatico(p_oficina uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare a public.avisos_automaticos;c public.clientes;begin
 if not private.has_feature(p_oficina,'automations') then return null;end if;
 select * into a from public.avisos_automaticos where oficina_id=p_oficina and situacao='aprovado' order by criado_em for update skip locked limit 1;if not found then return null;end if;
 select * into c from public.clientes where oficina_id=p_oficina and id=a.cliente_id and arquivado_em is null;
 if c.id is null or c.telefone_e164 is distinct from a.telefone_aprovado or not exists(select 1 from public.membros_oficina where oficina_id=p_oficina and usuario_id=a.aprovado_por and ativo and perfil in('owner','manager')) or (a.versao_orcamento_id is not null and not exists(select 1 from public.versoes_orcamento v join public.orcamentos q on q.id=v.orcamento_id and q.oficina_id=v.oficina_id where v.id=a.versao_orcamento_id and v.oficina_id=p_oficina and q.versao_atual_id=v.id and q.situacao='awaiting_approval' and v.expira_em>now())) then update public.avisos_automaticos set situacao='cancelado' where id=a.id;return null;end if;
 update public.avisos_automaticos set situacao='enviando',tentativa=gen_random_uuid(),iniciado_em=now() where id=a.id returning * into a;return jsonb_build_object('id',a.id,'tentativa',a.tentativa,'telefone',a.telefone_aprovado,'mensagem',a.mensagem);end $$;
create function public.concluir_aviso_automatico(p_id uuid,p_tentativa uuid,p_sucesso boolean) returns void language plpgsql security definer set search_path='' as $$begin update public.avisos_automaticos set situacao=case when p_sucesso then 'enviado' else 'incerto' end,enviado_em=case when p_sucesso then now() else null end where id=p_id and tentativa=p_tentativa and situacao='enviando';end $$;
create function public.reservar_sugestao_ia(p_oficina uuid,p_chave uuid,p_texto text) returns uuid language plpgsql security definer set search_path='' as $$
declare u uuid;r uuid;begin u:=private.require_staff(p_oficina);if not private.has_feature(p_oficina,'ai') then raise exception 'IA indisponível no plano.' using errcode='42501';end if;
 if length(trim(coalesce(p_texto,''))) not between 10 and 3000 or p_chave is null then raise exception 'Descreva o serviço em 10 a 3000 caracteres.' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended(p_oficina::text,0));select id into r from public.execucoes_ia where oficina_id=p_oficina and chave_idempotencia=p_chave;if found then raise exception 'Esta solicitação já foi processada. Consulte o histórico.' using errcode='22023';end if;
 if(select count(*) from public.execucoes_ia where oficina_id=p_oficina and criado_em>now()-interval '1 day')>=30 then raise exception 'Limite de 30 sugestões por dia atingido.' using errcode='22023';end if;
 insert into public.execucoes_ia(oficina_id,solicitado_por,tipo_tarefa,modelo,versao_instrucao_ia,chave_idempotencia,situacao) values(p_oficina,u,'resumo_cliente','configurado_no_servidor','1',p_chave,'running') returning id into r;return r;end $$;
do $$declare f record;begin for f in select p.oid::regprocedure assinatura,p.proname,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where p.proname in('aviso_andamento','consultar_automacoes','revisar_aviso','processar_lembretes_automaticos','reservar_aviso_automatico','concluir_aviso_automatico','reservar_sugestao_ia') loop execute format('revoke all on function %s from public,anon,authenticated',f.assinatura);if f.proname in('consultar_automacoes','revisar_aviso','reservar_sugestao_ia') then execute format('grant execute on function %s to authenticated',f.assinatura);elsif f.nspname='public' then execute format('grant execute on function %s to service_role',f.assinatura);end if;end loop;end $$;
notify pgrst,'reload schema';commit;
